def totals_by_category(csv_text):
    totals = {}
    if not csv_text:
        return totals
    lines = csv_text.splitlines()
    header_seen = False
    for line in lines:
        if not line.strip():
            continue
        parts = [p.strip() for p in line.split(",")]
        if not header_seen:
            header_seen = True
            if len(parts) >= 2 and parts[0].lower() == "category" and parts[1].lower() == "amount":
                continue
        if len(parts) < 2:
            continue
        category = parts[0]
        try:
            amount = int(parts[1])
        except ValueError:
            continue
        totals[category] = totals.get(category, 0) + amount
    return totals

